#include <stdint.h>
#include "stm32f10x.h"
#include "stm32f10x_gpio.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_adc.h"
#include "Delay.h"
#include "OLED.h"
#include "Key.h"
#include "Buzzer.h"
#include "Thermal.h"
#include "LightSensor.h"
#include "DHT11.h"
#include "MQ2.h"
#include "SERVO.h"
#include "led_pwm.h"
#include "motor.h"
#include "MenuSetting.h"
#include "MenuSelector.h"


int main(void)
{
    // 0. 初始化系统时钟和延时函数
    SystemInit();//配置系统时钟为72M	
	Delay_init(72);

    // 1. 初始化所有底层硬件
    OLED_Init();
    Key_Init();
    Buzzer_Init();
    Thermal_Init(); 
    LightSensor_Init();
    DHT11_Init();
    MQ2_Init();
    SERVO_Init();
    LED_PWM_Init();
    Motor_Init();


    // 2. 初始化菜单树
    MenuInit();

    while (1) 
    {
        // === 执行后台传感器读取与仲裁任务 ===
        Run_Background_Task();

        // 3. 获取按键输入
        uint8_t key_num = Key_GetNum();

        // 4. 根据按键执行菜单操作 (你需要根据实际按键顺序微调这里)
        if (key_num == 2) {
            SelectUP();        // SW2: 向上移动光标
        } 
        else if (key_num == 4) {
            SelectDOWN();      // SW4: 向下移动光标
        } 
        else if (key_num == 3) {
            SelectINorRUN();   // SW3: 确认 / 进入子菜单 / 执行函数
        } 
        else if (key_num == 1) {
            SelectOut();       // SW1: 返回上一级
        }

        // 5. 刷新菜单显示
        PrintSelector();

        // 6. 稍微延时，作为简单的按键防抖和控制刷新率
        Delay_ms(50); 
    }
}
